# owner: platform
"""Seating charts: students sorted by last name, in rows."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _sort_key(student: Student) -> tuple:
    last = student.last_name.lower()
    return (last, student.first_name.lower())


def _check_inputs(students: List[Student], seats: int):
    if seats <= 0:
        raise ProjectError("seats per row must be positive")
    if not students:
        raise ProjectError("no students to seat")


def _chunk(items: list, size: int) -> List[list]:
    return [
        items[start:start + size]
        for start in range(0, len(items), size)
    ]


def seating_rows(students: List[Student], seats: int):
    """One line per row: `Row 1: Dunmere, Piet | ...`."""
    _check_inputs(students, seats)
    groups = _chunk(sorted(students, key=_sort_key), seats)
    return [_format_row(index, group) for index, group
            in enumerate(groups, 1)]


def _format_row(number: int, group: List[Student]) -> str:
    names = " | ".join(item.display_name for item in group)
    return f"Row {number}: {names}"

