# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def make_student(last, first):
    return Student("id-" + last, last, first, "A")


PEOPLE = [
    make_student("Halloway", "Juno"),
    make_student("Dunmere", "Piet"),
    make_student("Armitage", "Sol"),
]


class SeatingTests(unittest.TestCase):
    def test_sorted_and_chunked(self):
        self.assertEqual(
            seating_rows(PEOPLE, 2),
            [
                "Row 1: Armitage, Sol | Dunmere, Piet",
                "Row 2: Halloway, Juno",
            ],
        )

    def test_single_wide_row(self):
        rows = seating_rows(PEOPLE, 10)
        self.assertEqual(len(rows), 1)

    def test_ties_break_on_first_name(self):
        pair = [
            make_student("Lund", "Zed"),
            make_student("lund", "Abe"),
        ]
        expect = ["Row 1: lund, Abe | Lund, Zed"]
        self.assertEqual(seating_rows(pair, 2), expect)

    def test_input_not_mutated(self):
        before = list(PEOPLE)
        seating_rows(PEOPLE, 2)
        self.assertEqual(PEOPLE, before)

    def test_bad_seat_counts(self):
        for seats in (0, -3):
            with self.assertRaises(ProjectError):
                seating_rows(PEOPLE, seats)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 3)


if __name__ == "__main__":
    unittest.main()
